package com.payroll.service; import com.payroll.model.Employee; import com.payroll.repository.EmployeeRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service public class EmployeeService { private final EmployeeRepository repo; private final AuditService audit; public EmployeeService(EmployeeRepository r,AuditService a){repo=r;audit=a;} public List<Employee> search(String q){return q==null||q.isBlank()?repo.findAll():repo.findByFullNameContainingIgnoreCaseOrEmployeeCodeContainingIgnoreCase(q,q);} public Employee get(Long id){return repo.findById(id).orElseThrow(()->new NoSuchElementException("Employee not found"));} @Transactional public Employee create(Employee e,String u){if(repo.findByEmployeeCode(e.getEmployeeCode()).isPresent())throw new IllegalArgumentException("Employee ID already exists"); Employee saved=repo.save(e);audit.record(u,"CREATE","Employee",saved.getId().toString(),"Created "+saved.getFullName());return saved;} @Transactional public Employee update(Long id,Employee e,String u){Employee x=get(id); if(!x.getEmployeeCode().equals(e.getEmployeeCode())&&repo.findByEmployeeCode(e.getEmployeeCode()).isPresent())throw new IllegalArgumentException("Employee ID already exists"); x.setEmployeeCode(e.getEmployeeCode());x.setFullName(e.getFullName());x.setEmail(e.getEmail());x.setPhone(e.getPhone());x.setDepartment(e.getDepartment());x.setDesignation(e.getDesignation());x.setBasicSalary(e.getBasicSalary());x.setJoiningDate(e.getJoiningDate());audit.record(u,"UPDATE","Employee",id.toString(),"Updated "+x.getFullName());return repo.save(x);} @Transactional public void delete(Long id,String u){Employee x=get(id);repo.delete(x);audit.record(u,"DELETE","Employee",id.toString(),"Deleted "+x.getFullName());} }